package main

import (
	"context"
	"flag"
	"os"
	"os/signal"

	"github.com/maoxiaoyue/hypgo/pkg/hidb"
	"github.com/maoxiaoyue/hypgo/pkg/hidb/pg"

	"legagent/app/services"
)

// runImportLegislators 把 data/legislators/legislators.json 寫入 PostgreSQL。
//
//	go run . import-legislators
//	go run . import-legislators -file path/legislators.json
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 寫入資料庫是明確的維運動作，與伺服器啟動分開，也讓伺服器在資料庫離線時仍可提供法規檢索
// @ai:input args 子命令參數
// @ai:output none
// @ai:sideeffect 建立資料表並寫入 PostgreSQL、失敗時 os.Exit
func runImportLegislators(args []string) {
	fs := flag.NewFlagSet("import-legislators", flag.ExitOnError)
	cfgPath := fs.String("config", defaultConfigPath, "config.yaml 路徑")
	file := fs.String("file", "data/legislators/legislators.json", "立委名單 JSON 路徑")
	_ = fs.Parse(args)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	cfg, log := mustLoad(*cfgPath)
	roster, err := services.LoadLegislatorRoster(*file)
	if err != nil {
		log.Error("load roster failed", "path", *file, "err", err)
		os.Exit(1)
	}
	db, err := hidb.NewWithInterface(&cfg.Database, hidb.WithDialect(pg.New()))
	if err != nil {
		log.Error("connect database failed", "err", err)
		os.Exit(1)
	}
	defer db.Close()

	stats, err := services.NewLegislatorsService(db, log).Import(ctx, roster)
	if err != nil {
		db.Close()
		os.Exit(1)
	}
	log.Info("import done", "legislators", stats.Legislators, "term_records", stats.TermRecords, "terms", stats.Terms)
}
